-- DISI rollback of Migration 050 (international benchmark expansion and probability-support audit).
-- database/release/sql/rollback-050.sql, generated by database/research/050/build.mjs from the same research files as the migration.
--
-- Use only if a production failure requires it. One transaction, guarded. It removes exactly what 050 added - the 2015 / 2016 benchmark
-- players, signings, population members and populations, the 050 rankings, the 050 outcome audits, outcomes and evidence, the two legacy
-- identities - restores the stored 041 model evaluation rows exactly, restores the 044 definition of disi_executive_overview() and the 045b
-- definition of disi_refresh_product_snapshots(), and refreshes the product snapshots once. The source rows stay as provenance.
--
-- The 026 evaluation guard seals ACTIVE rankings (a sealed point-in-time observation is never deleted by research). Restoring the exact
-- pre-050 state is the one sanctioned exception: inside this transaction only, the two guard triggers are disabled, exactly the 050
-- rankings are removed, and the triggers are enabled again before commit (proved below). 050 can be applied again after this rollback.

begin;

create temporary table _r050 on commit drop as
select $r050${{payload_json}}$r050$::jsonb as j;

-- ===========================================================================
-- 1. GUARDS
-- ===========================================================================

do $$
declare
  n int;
begin
  if (select count(*) from public.signing_populations where population_key in (select jsonb_array_elements_text(j -> 'populations') from _r050)) = 0 then
    raise exception 'rollback-050: Migration 050 is not applied';
  end if;
  -- later research must not depend on what is removed
  select count(*) into n from public.players pl
    where pl.slug in (select x ->> 'slug' from _r050, jsonb_array_elements(j -> 'new_players') x)
      and (exists (select 1 from public.player_season_stints s where s.player_id = pl.id)
        or exists (select 1 from public.development_milestones m where m.player_id = pl.id)
        or exists (select 1 from public.player_mlb_team_season_war w where w.player_id = pl.id or w.bref_id = pl.bref_id)
        or exists (select 1 from public.transaction_event_assets a where a.player_id = pl.id or a.mlb_id = pl.mlb_id::text)
        or exists (select 1 from public.player_network_relationships r where r.player_id = pl.id)
        or (select count(*) from public.signings s where s.player_id = pl.id) <> 1
        or (select count(*) from public.player_evaluations e where e.player_id = pl.id) <> 1);
  if n > 0 then
    raise exception 'rollback-050: later research depends on % of the 050 benchmark players; rollback refused', n;
  end if;
end $$;

-- ===========================================================================
-- 2. THE 050 RANKINGS (the one sanctioned removal of sealed rows)
-- ===========================================================================

create temporary table _r050_eval on commit drop as
select e.id from public.player_evaluations e
join public.scouting_publications pub on pub.id = e.publication_id and pub.publication_slug = (select j ->> 'publication_slug' from _r050)
join public.players pl on pl.id = e.player_id
where pl.slug in (select x ->> 'slug' from _r050, jsonb_array_elements(j -> 'new_players') x)
union
select e.id from public.player_evaluations e
join public.scouting_publications pub on pub.id = e.publication_id and pub.publication_slug = (select j ->> 'publication_slug' from _r050)
join public.players pl on pl.id = e.player_id
join public.player_evaluation_rankings r on r.evaluation_id = e.id
join _r050 on true
join lateral jsonb_array_elements(j -> 'dodgers_evaluations') d on d ->> 'slug' = pl.slug
where r.scope_label = d ->> 'scope_label' and e.evaluation_date = (d ->> 'evaluation_date')::date;

alter table public.player_evaluations disable trigger player_evaluations_guard;
alter table public.player_evaluation_rankings disable trigger player_evaluation_rankings_immutable;
delete from public.player_evaluation_rankings where evaluation_id in (select id from _r050_eval);
delete from public.player_evaluations where id in (select id from _r050_eval);
alter table public.player_evaluation_rankings enable trigger player_evaluation_rankings_immutable;
alter table public.player_evaluations enable trigger player_evaluations_guard;

-- ===========================================================================
-- 3. THE BENCHMARK PLAYERS, SIGNINGS, MEMBERS, AUDITS, OUTCOMES AND EVIDENCE
-- ===========================================================================

create temporary table _r050_players on commit drop as
select pl.id, pl.slug from public.players pl where pl.slug in (select x ->> 'slug' from _r050, jsonb_array_elements(j -> 'new_players') x);

delete from public.evidence where entity_type = 'signing' and entity_id in (select s.id from public.signings s where s.player_id in (select id from _r050_players));
delete from public.evidence where entity_type = 'player' and entity_id in (select id from _r050_players);
delete from public.signing_population_member_sources where member_id in (select m.id from public.signing_population_members m
  join public.signings s on s.id = m.signing_id where s.player_id in (select id from _r050_players));
delete from public.signing_population_members where signing_id in (select s.id from public.signings s where s.player_id in (select id from _r050_players));
delete from public.outcomes where player_id in (select id from _r050_players);
delete from public.outcome_audits where player_id in (select id from _r050_players);
delete from public.outcome_evidence where player_id in (select id from _r050_players);
delete from public.player_aliases where player_id in (select id from _r050_players);
delete from public.signings where player_id in (select id from _r050_players);
delete from public.players where id in (select id from _r050_players);

-- ===========================================================================
-- 4. THE LEGACY IDENTITIES: back to unresolved, exactly as 035 left them
-- ===========================================================================

create temporary table _r050_legacy on commit drop as
select pl.id, x ->> 'mlb_id' as mlb_id, x ->> 'alias' as alias
from _r050, jsonb_array_elements(j -> 'legacy') x join public.players pl on pl.slug = x ->> 'slug';

delete from public.outcomes where player_id in (select id from _r050_legacy);
delete from public.outcome_audits where player_id in (select id from _r050_legacy);
delete from public.outcome_evidence where player_id in (select id from _r050_legacy);
delete from public.evidence where entity_type = 'player' and entity_id in (select id from _r050_legacy) and field_name in ('mlb_id', 'birth_date', 'bref_id');
delete from public.player_aliases a using _r050_legacy l where a.player_id = l.id and a.alias = l.alias and a.alias_type = 'MLB_RECORD_NAME';
update public.players pl set mlb_id = null, birth_date = null, bref_id = null, mlb_debut_date = null
from _r050_legacy l where pl.id = l.id and pl.mlb_id = l.mlb_id::bigint;

-- ===========================================================================
-- 5. POPULATIONS, THE STORED EVALUATION AND THE EXECUTIVE FUNCTION
-- ===========================================================================

create temporary table _r050_cov on commit drop as
select sp.legacy_coverage_id as id from public.signing_populations sp
where sp.population_key in (select jsonb_array_elements_text(j -> 'populations') from _r050) and sp.legacy_coverage_id is not null;
delete from public.signing_populations where population_key in (select jsonb_array_elements_text(j -> 'populations') from _r050);
delete from public.signing_census_coverage where id in (select id from _r050_cov);

update public.outcome_model_evaluations m set
  model_version = x ->> 'model_version', validation_method = x ->> 'validation_method',
  feature_list = array(select jsonb_array_elements_text(x -> 'feature_list')), training_populations = array(select jsonb_array_elements_text(x -> 'training_populations')),
  evaluated_rows = (x ->> 'evaluated_rows')::int, positive_n = (x ->> 'positive_n')::int, folds = (x ->> 'folds')::int,
  brier_score = (x ->> 'brier_score')::numeric, log_loss = (x ->> 'log_loss')::numeric, auc = (x ->> 'auc')::numeric,
  brier_skill_vs_base_rate = (x ->> 'brier_skill_vs_base_rate')::numeric, calibration_bins = x -> 'calibration_bins', decision = x ->> 'decision',
  decision_reason = x ->> 'decision_reason', training_fingerprint = x ->> 'training_fingerprint', data_as_of_date = (x ->> 'data_as_of_date')::date
from _r050, jsonb_array_elements(j -> 'evaluation_041') x
where m.target_key = x ->> 'target_key' and m.model_key = x ->> 'model_key';

{{executive_function_044}}

{{refresh_function_045b}}

-- ===========================================================================
-- 6. POSTCONDITIONS AND ONE REFRESH
-- ===========================================================================

do $$
declare
  k text;
begin
  if (select count(*) from public.players) <> (select (j #>> '{baseline,counts,players}')::int from _r050)
     or (select count(*) from public.signings where record_scope = 'MLB_PIPELINE_TOP_PROSPECT') <> (select (j #>> '{baseline,counts,benchmark_signings}')::int from _r050)
     or (select count(*) from public.outcome_audits) <> (select (j #>> '{baseline,counts,outcome_audits}')::int from _r050)
     or (select count(*) from public.outcomes) <> (select (j #>> '{baseline,counts,outcomes}')::int from _r050)
     or (select count(*) from public.player_evaluations) <> (select (j #>> '{baseline,counts,player_evaluations}')::int from _r050)
     or (select count(*) from public.signing_populations) <> (select (j #>> '{baseline,counts,signing_populations}')::int from _r050)
     or (select count(*) from public.signing_population_members) <> (select (j #>> '{baseline,counts,population_members}')::int from _r050)
     or (select count(*) from public.signing_census_coverage) <> (select (j #>> '{baseline,counts,census_coverage_rows}')::int from _r050) then
    raise exception 'rollback-050 postcondition: the pre-050 counts are not restored';
  end if;
  if exists (select 1 from public.outcome_model_evaluations where training_fingerprint <> (select j #>> '{baseline,evaluation,0,training_fingerprint}' from _r050)) then
    raise exception 'rollback-050 postcondition: the stored 041 evaluation is not restored';
  end if;
  select md5(prosrc) into k from pg_proc where proname = 'disi_executive_overview' and pronamespace = 'public'::regnamespace;
  if k is distinct from (select j #>> '{executive,old_md5}' from _r050) then
    raise exception 'rollback-050 postcondition: disi_executive_overview() is not the 044 definition';
  end if;
  select md5(prosrc) into k from pg_proc where proname = 'disi_refresh_product_snapshots' and pronamespace = 'public'::regnamespace;
  if k is distinct from (select j #>> '{refresh,old_md5}' from _r050) then
    raise exception 'rollback-050 postcondition: disi_refresh_product_snapshots() is not the 045b definition';
  end if;
  if exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid where c.relname in ('player_evaluations', 'player_evaluation_rankings')
             and not t.tgisinternal and t.tgenabled <> 'O') then
    raise exception 'rollback-050 postcondition: an evaluation guard trigger is not enabled';
  end if;
end $$;

select * from public.disi_refresh_product_snapshots();

commit;
